-- Preview only: gallery mappings and restricted buyer evidence. Do not apply to production without review.
create extension if not exists pgcrypto;
create table if not exists public.gallery_folder_media (folder_id uuid not null references public.gallery_folders(id) on delete cascade, media_id uuid not null references public.media_uploads(id) on delete cascade, sort_order int not null default 0, primary key(folder_id,media_id));
create index if not exists gallery_link_media_idx on public.gallery_folder_media(media_id);
alter table public.gallery_folder_media enable row level security;
revoke all on public.gallery_folder_media from public,anon,authenticated;
grant select on public.gallery_folder_media to anon,authenticated;
grant insert,update,delete on public.gallery_folder_media to authenticated;
drop policy if exists gallery_link_public on public.gallery_folder_media;
create policy gallery_link_public on public.gallery_folder_media for select to anon,authenticated using (exists(select 1 from public.media_uploads m where m.id=media_id and m.is_active));
drop policy if exists gallery_link_admin on public.gallery_folder_media;
create policy gallery_link_admin on public.gallery_folder_media for all to authenticated using(public.is_admin()) with check(public.is_admin());
create table if not exists public.gallery_folder_covers(folder_id uuid primary key,media_id uuid not null,foreign key(folder_id,media_id) references public.gallery_folder_media(folder_id,media_id) on delete cascade);
alter table public.gallery_folder_covers enable row level security;
revoke all on public.gallery_folder_covers from public,anon,authenticated;
grant select on public.gallery_folder_covers to anon,authenticated;
grant insert,update,delete on public.gallery_folder_covers to authenticated;
drop policy if exists gallery_cover_public on public.gallery_folder_covers;
create policy gallery_cover_public on public.gallery_folder_covers for select to anon,authenticated using(exists(select 1 from public.media_uploads m where m.id=media_id and m.is_active and m.media_type='image'));
drop policy if exists gallery_cover_admin on public.gallery_folder_covers;
create policy gallery_cover_admin on public.gallery_folder_covers for all to authenticated using(public.is_admin()) with check(public.is_admin());
create table if not exists public.buyer_evidence(id uuid primary key default gen_random_uuid(),category text not null check(category in ('company','licences','geology','assets','contracts','finance','safety')),title text not null check(length(trim(title)) between 3 and 180),status text not null default 'requested' check(status in ('requested','reviewing','verified','restricted')),reference text not null default '' check(length(reference)<=500),notes text not null default '' check(length(notes)<=2000),storage_path text unique,created_at timestamptz not null default now());
alter table public.buyer_evidence enable row level security;
revoke all on public.buyer_evidence from public,anon,authenticated;
grant select,insert,update,delete on public.buyer_evidence to authenticated;
drop policy if exists buyer_evidence_admin on public.buyer_evidence;
create policy buyer_evidence_admin on public.buyer_evidence for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('ggmc-buyer-documents','ggmc-buyer-documents',false,10485760,ARRAY['application/pdf','image/jpeg','image/png','image/webp']::text[]) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists buyer_docs_admin_select on storage.objects;
create policy buyer_docs_admin_select on storage.objects for select to authenticated using(bucket_id='ggmc-buyer-documents' and public.is_admin());
drop policy if exists buyer_docs_admin_insert on storage.objects;
create policy buyer_docs_admin_insert on storage.objects for insert to authenticated with check(bucket_id='ggmc-buyer-documents' and public.is_admin());
drop policy if exists buyer_docs_admin_delete on storage.objects;
create policy buyer_docs_admin_delete on storage.objects for delete to authenticated using(bucket_id='ggmc-buyer-documents' and public.is_admin());
